import {officialMapData} from './official-map-data.mjs';
import {internationalMapData} from './international-map-data.mjs';

const components = new Map([
  ['VIS-002', `<figure class="learning-visual" id="vis-002"><div class="wd-explainer" role="group" aria-labelledby="vis-002-title" aria-describedby="vis-002-summary"><p class="wd-explainer__eyebrow">WineDaddy quick explainer</p><p class="wd-explainer__title" id="vis-002-title">Dry does not mean flavourless.</p><p class="wd-explainer__intro">Dryness and fruit flavour describe different parts of the wine experience.</p><div class="wd-explainer__scales"><section class="wd-scale wd-scale--dryness" aria-labelledby="vis-002-dryness"><p class="wd-scale__title" id="vis-002-dryness">Dryness</p><p class="wd-scale__question">How much sweetness do you perceive?</p><div class="wd-scale__track" aria-hidden="true"><span class="wd-scale__marker"></span></div><div class="wd-scale__ends"><strong>Dry</strong><strong>Sweet</strong></div><p class="wd-scale__reading">Little perceptible sweetness</p></section><section class="wd-scale wd-scale--fruit" aria-labelledby="vis-002-fruit"><p class="wd-scale__title" id="vis-002-fruit">Fruit flavour</p><p class="wd-scale__question">How strongly do fruit aromas and flavours show?</p><div class="wd-scale__track" aria-hidden="true"><span class="wd-scale__marker"></span></div><div class="wd-scale__ends"><strong>Subtle</strong><strong>Intense</strong></div><p class="wd-scale__reading">Pronounced fruit character</p></section></div><p class="wd-explainer__summary" id="vis-002-summary"><span>Both can be true</span><strong>A wine can be dry and intensely fruity.</strong></p></div><figcaption><strong>Dryness describes perceived sweetness; fruitiness describes aroma and flavour.</strong> A wine can be dry and intensely fruity at the same time.</figcaption></figure>`],
  ['VIS-009', '<figure class="learning-visual" id="vis-009"><div class="wd-explainer wd-component wd-component--label_explainer" role="group" aria-labelledby="VIS-009-title" aria-describedby="VIS-009-summary"><p class="wd-explainer__eyebrow">WineDaddy quick explainer</p><p class="wd-explainer__title" id="VIS-009-title">How to read a wine label</p><p class="wd-explainer__intro">Separate identity, origin and practical facts from branding and marketing language.</p><div class="wd-component__items"><section class="wd-component__item wd-component__item--primary" data-key="producer-brand"><p class="wd-component__number" aria-hidden="true">1</p><p class="wd-component__item-title">Producer or brand</p><p class="wd-component__description">Identifies the maker, business or commercial range—but these may be different names.</p></section><section class="wd-component__item wd-component__item--neutral" data-key="vintage"><p class="wd-component__number" aria-hidden="true">2</p><p class="wd-component__item-title">Vintage</p><p class="wd-component__description">Generally the grape-harvest year, not the bottling or release year.</p><p class="wd-component__value">2024</p></section><section class="wd-component__item wd-component__item--primary" data-key="variety-blend"><p class="wd-component__number" aria-hidden="true">3</p><p class="wd-component__item-title">Variety or blend</p><p class="wd-component__description">Names the grape when stated. Some wines name several varieties or none.</p><p class="wd-component__value">Shiraz</p></section><section class="wd-component__item wd-component__item--secondary" data-key="region-gi"><p class="wd-component__number" aria-hidden="true">4</p><p class="wd-component__item-title">Region or GI</p><p class="wd-component__description">Describes claimed grape origin. It is not a quality score.</p><p class="wd-component__value">Yarra Valley</p></section><section class="wd-component__item wd-component__item--neutral" data-key="practical-details"><p class="wd-component__number" aria-hidden="true">5</p><p class="wd-component__item-title">Practical details</p><p class="wd-component__description">Alcohol, volume and standard drinks describe different things. Check the whole package.</p><p class="wd-component__value">13.5% alc/vol · 750 mL</p></section></div><p class="wd-explainer__summary" id="VIS-009-summary"><span>Remember</span><strong>A label is a starting point—not a quality guarantee.</strong></p></div><figcaption>Read facts before flourish. This fictional label is explanatory, not a compliance template.</figcaption></figure>']
]);

const esc = value => String(value).replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));

function explainer({id, title, intro, items, summary, caption, family = 'cards'}) {
  const itemHtml = items.map((item, index) => `<section class="wd-batch-card wd-batch-card--${esc(item.tone || 'neutral')}"><p class="wd-batch-card__number" aria-hidden="true">${index + 1}</p><p class="wd-batch-card__title">${esc(item.title)}</p><p class="wd-batch-card__text">${esc(item.text)}</p>${item.note ? `<p class="wd-batch-card__note">${esc(item.note)}</p>` : ''}</section>`).join('');
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-batch wd-batch--${family}" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy quick explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-batch__items">${itemHtml}</div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>${esc(caption)}</figcaption></figure>`;
}

components.set('VIS-003', explainer({id:'VIS-003',title:'Why Cabernet Sauvignon can taste different',intro:'The grape matters, but it is only one part of the finished wine.',items:[{title:'Place',text:'Climate, soil, elevation and water availability influence how grapes ripen.',tone:'sage'},{title:'Season',text:'Vintage weather changes ripeness, acidity and growing conditions.',tone:'gold'},{title:'Vineyard',text:'Site, yield, harvest timing and canopy decisions shape the fruit.',tone:'wine'},{title:'Winemaking',text:'Extraction, fermentation, blending and maturation influence the result.',tone:'ink'}],summary:'Variety gives you a useful starting point—not a fixed flavour guarantee.',caption:'A framework for variation, not a recipe for predicting every Cabernet Sauvignon.'}));
components.set('VIS-005', explainer({id:'VIS-005',title:'Why nearby vineyard sites can differ',intro:'Elevation and terrain can change growing conditions over surprisingly short distances.',items:[{title:'Elevation',text:'Higher sites are often cooler, but aspect and exposure still matter.',tone:'sage'},{title:'Slope and aspect',text:'The direction and angle of a slope affect sunlight, drainage and airflow.',tone:'gold'},{title:'Local weather',text:'Rainfall, wind, frost risk and heat vary across a region.',tone:'wine'},{title:'Vineyard response',text:'Growers adapt variety, canopy, irrigation and harvest decisions to the site.',tone:'ink'}],summary:'A regional name describes origin; it does not make every vineyard identical.',caption:'Site influences interact. No single factor determines the finished wine.'}));
components.set('VIS-006', explainer({id:'VIS-006',title:'What a wine region tells you—and what it does not',intro:'A geographical indication protects origin. It is not a recipe or quality score.',items:[{title:'The label can tell you',text:'The wine claims a regulated geographic origin under the applicable rules.',tone:'sage'},{title:'The region may suggest',text:'Common varieties, climate patterns and broad regional tendencies.',tone:'gold'},{title:'The label cannot guarantee',text:'A specific flavour, quality level, vineyard method or winemaking choice.',tone:'wine'},{title:'Read the whole bottle',text:'Combine origin with producer, variety, vintage and practical details.',tone:'ink'}],summary:'Origin is evidence about place—not a promise about taste.',caption:'Regional tendencies are useful context, but individual wines still vary.'}));
components.set('VIS-008', explainer({id:'VIS-008',title:'How oxidation can develop in wine',intro:'Oxygen exposure can begin a chain of gradual chemical changes.',items:[{title:'Exposure',text:'Oxygen can enter during winemaking, storage, packaging or after opening.',tone:'sage'},{title:'Reaction over time',text:'Wine compounds react at rates influenced by temperature and wine composition.',tone:'gold'},{title:'Possible changes',text:'Fresh aromas may fade while colour darkens and nutty or stale notes develop.',tone:'wine'},{title:'Slow further change',text:'Resealing, cooling and reducing air exposure can help, but cannot reverse it.',tone:'ink'}],summary:'Oxygen exposure is not automatically a fault; whether it suits the intended style matters.',caption:'A simplified pathway. Oxidation involves several compounds and reactions.'}));
components.set('VIS-013', explainer({id:'VIS-013',title:'Wine and seafood: practical starting points',intro:'Start with the preparation and sauce—not only the species of seafood.',items:[{title:'Raw or delicate',text:'Try a light, fresh wine that will not overwhelm subtle flavours.',note:'Examples: dry sparkling, crisp light white',tone:'sage'},{title:'Grilled or meaty',text:'Look for more body and texture while keeping enough freshness.',note:'Examples: fuller white, dry rosé',tone:'gold'},{title:'Rich or creamy',text:'Match the sauce weight and use acidity to keep the pairing lively.',note:'Examples: textured Chardonnay-style white',tone:'wine'},{title:'Spicy or aromatic',text:'Consider fruit intensity, modest alcohol and the dish’s heat level.',note:'Examples: aromatic white, off-dry option',tone:'ink'}],summary:'Cooking method, sauce and intensity usually matter more than a rigid colour rule.',caption:'These are flexible starting points, not guaranteed matches.'}));
components.set('VIS-014', explainer({id:'VIS-014',title:'Whole-bunch fermentation: three broad pathways',intro:'The amount of retained stems changes the fermenting material, but does not determine quality.',items:[{title:'Destemmed',text:'Most or all berries are separated from stems before fermentation.',tone:'sage'},{title:'Partial whole bunch',text:'A chosen portion of intact bunches ferments with destemmed fruit.',tone:'gold'},{title:'High whole bunch',text:'Most or nearly all bunches enter the ferment with stems retained.',tone:'wine'},{title:'What else matters',text:'Ripeness, stem condition, vessel, temperature, extraction and timing all interact.',tone:'ink'}],summary:'Whole-bunch use is a spectrum of choices—not a single fixed technique.',caption:'Simplified comparison; producers may combine or adapt these approaches.'}));
components.set('VIS-021', explainer({id:'VIS-021',title:'What alcoholic fermentation changes',intro:'Yeast uses fermentable grape sugars and transforms grape juice or must into wine.',items:[{title:'Grape sugar',text:'Mainly glucose and fructose provide the starting material.',tone:'sage'},{title:'Yeast activity',text:'Yeast metabolises sugar while conditions such as temperature and nutrients affect progress.',tone:'gold'},{title:'Main outputs',text:'Ethanol, carbon dioxide and heat are produced as sugar falls.',tone:'wine'},{title:'Style effects',text:'Other fermentation compounds can influence aroma, flavour and texture.',tone:'ink'}],summary:'Sugar → ethanol + carbon dioxide + heat, with other compounds also formed.',caption:'A teaching simplification of alcoholic fermentation, not a complete chemical equation.'}));
components.set('VIS-023', explainer({id:'VIS-023',title:'Where wine aromas come from',intro:'Aroma groups describe broad origins; they do not tell you the wine literally contains those ingredients.',items:[{title:'Primary',text:'Aromas associated mainly with grapes and fermentation of the fruit.',note:'Fruit, floral and herbal families',tone:'sage'},{title:'Secondary',text:'Aromas associated with winemaking and post-fermentation processes.',note:'Yeast, lees and malolactic influences',tone:'gold'},{title:'Tertiary',text:'Aromas that develop through maturation and ageing.',note:'Bottle and oak-ageing development',tone:'wine'},{title:'Overlap is normal',text:'Real aromas can have several origins, and classifications vary.',tone:'ink'}],summary:'Primary, secondary and tertiary are a useful framework—not three sealed boxes.',caption:'Aroma classification is interpretive; categories can overlap.'}));
components.set('VIS-022', explainer({id:'VIS-022',title:'How grape skins help make red wine red',intro:'Most colour comes from pigments in dark grape skins, extracted while juice and skins are together.',items:[{title:'Crush or break',text:'Dark-skinned grapes release pale juice while the skins remain in the fermenting material.',tone:'sage'},{title:'Skin contact',text:'Pigments called anthocyanins move from skins into the liquid.',tone:'gold'},{title:'Fermentation',text:'Time, temperature, alcohol and cap management influence extraction.',tone:'wine'},{title:'Pressing',text:'Wine is separated from the skins after the chosen contact period.',tone:'ink'}],summary:'Red colour mainly comes from skin contact—not from red grape juice.',caption:'A simplified extraction pathway. Colour and tannin are related but not identical.'}));
components.set('VIS-028', explainer({id:'VIS-028',title:'French oak vs American oak',intro:'Oak origin can influence sensory tendencies, but barrel construction and wine choices also matter.',items:[{title:'French oak',text:'Often associated with finer-grained structure and restrained spice or savoury notes.',tone:'sage'},{title:'American oak',text:'Often associated with more overt vanilla, coconut, sweet spice or dill-like notes.',tone:'gold'},{title:'Not a guarantee',text:'Forest, grain, seasoning, cooperage and toast can change the result.',tone:'wine'},{title:'Wine context',text:'Oak age, barrel size, time and the wine itself may matter as much as origin.',tone:'ink'}],summary:'Oak origin suggests tendencies; it does not predict flavour by itself.',caption:'Broad sensory associations vary by barrel, wine and maturation choices.'}));
components.set('VIS-029', explainer({id:'VIS-029',title:'New oak vs previously filled oak',intro:'A barrel’s fill history changes how strongly it contributes oak-derived flavour.',items:[{title:'New or first-fill',text:'Usually contributes the strongest extractable oak aroma, flavour and tannin.',tone:'sage'},{title:'Second-fill',text:'Often contributes less overt oak character than its first use.',tone:'gold'},{title:'Older or neutral',text:'May add little obvious oak flavour while still acting as a maturation vessel.',tone:'wine'},{title:'Other variables',text:'Size, toast, age, time and wine composition change the effect.',tone:'ink'}],summary:'Less oak flavour does not mean the barrel has stopped influencing maturation.',caption:'Fill-history terms are useful shorthand, not exact flavour measurements.'}));
components.set('VIS-030', explainer({id:'VIS-030',title:'How cold stabilisation works',intro:'The winery encourages tartrate crystals to form before the wine reaches the bottle.',items:[{title:'Cool the wine',text:'Wine is held at a low controlled temperature.',tone:'sage'},{title:'Encourage crystals',text:'Potassium bitartrate becomes less soluble and begins to crystallise.',tone:'gold'},{title:'Separate deposits',text:'The formed crystals are removed through settling, racking or filtration.',tone:'wine'},{title:'Bottle the wine',text:'The risk of harmless crystals appearing later is reduced, not universally eliminated.',tone:'ink'}],summary:'Cold stabilisation manages appearance; tartrate crystals are harmless.',caption:'A simplified four-step process. Winery methods and stability targets vary.'}));
components.set('VIS-032', explainer({id:'VIS-032',title:'How orange wine differs from white and rosé',intro:'Colour depends on grape colour and how long juice remains with skins.',items:[{title:'Typical white',text:'White grapes are usually pressed with limited skin contact before fermentation.',tone:'sage'},{title:'Orange wine',text:'White grapes ferment or macerate with their skins for an extended period.',tone:'gold'},{title:'Rosé',text:'Dark grapes generally have shorter skin contact than red wine.',tone:'wine'},{title:'Possible effects',text:'Longer white-grape skin contact can deepen colour and add phenolic texture.',tone:'ink'}],summary:'Orange wine is skin-contact white wine—not wine made from oranges.',caption:'Production methods vary; colour alone does not define sweetness or quality.'}));
components.set('VIS-033', explainer({id:'VIS-033',title:'Traditional-method sparkling wine',intro:'The bubbles are created by a second fermentation inside the bottle.',items:[{title:'Base wine',text:'A still base wine is prepared before the sparkling stage.',tone:'sage'},{title:'Second fermentation',text:'Yeast and sugar are added and carbon dioxide is trapped in the sealed bottle.',tone:'gold'},{title:'Lees ageing',text:'The wine rests with spent yeast, which may influence texture and aroma.',tone:'wine'},{title:'Finish the bottle',text:'Sediment is moved, removed, and the bottle is topped and closed.',tone:'ink'}],summary:'The defining feature is the second fermentation in the bottle.',caption:'A simplified sequence covering tirage, lees ageing, riddling, disgorgement and finishing.'}));
components.set('VIS-042', explainer({id:'VIS-042',title:'Four ways grapes and wines can come together',intro:'“Blend” can describe several different structures and moments in production.',items:[{title:'Wine blend',text:'Finished lots or components are combined to create the final wine.',tone:'sage'},{title:'Co-fermentation',text:'Different grapes or components ferment together rather than only being blended later.',tone:'gold'},{title:'Field blend',text:'Different varieties grow together in one vineyard and may be harvested together.',tone:'wine'},{title:'Single varietal',text:'One grape variety supplies the dominant or declared identity under applicable rules.',tone:'ink'}],summary:'The important question is what was combined—and when.',caption:'These categories can overlap in real production and labelling rules vary.'}));
components.set('VIS-044', explainer({id:'VIS-044',title:'How dealcoholised wine is made',intro:'Dealcoholised wine begins as fermented wine before some or most alcohol is removed.',items:[{title:'Make wine',text:'Grapes are fermented so the starting liquid is wine.',tone:'sage'},{title:'Separate alcohol',text:'A physical process such as membrane separation or vacuum distillation may be used.',tone:'gold'},{title:'Rebalance',text:'Producers may adjust aroma, texture, sweetness, acidity or dissolved gas within legal rules.',tone:'wine'},{title:'Package and label',text:'The final alcohol level and product description must meet applicable requirements.',tone:'ink'}],summary:'Dealcoholisation happens after fermentation; methods and final products vary.',caption:'A variable production pathway, not a claim that every producer uses the same technology.'}));
components.set('VIS-001', explainer({id:'VIS-001',title:'Cabernet Sauvignon at a glance',intro:'A useful starting profile for one of the world’s major red-wine grapes.',items:[{title:'Fruit',text:'Blackcurrant and other dark-fruit associations are common, with red fruit in some examples.',tone:'sage'},{title:'Structure',text:'Often medium to full bodied, with noticeable tannin and acidity.',tone:'gold'},{title:'Savoury notes',text:'Herbal, leafy, cedar or tobacco-like characters may appear.',tone:'wine'},{title:'Variation',text:'Climate, site, vintage, blending, extraction and oak all change the result.',tone:'ink'}],summary:'Cabernet has recognisable tendencies—not a single fixed taste.',caption:'A broad beginner profile. Individual wines can sit well outside it.'}));
components.set('VIS-010', explainer({id:'VIS-010',title:'One grape, two familiar names',intro:'Zinfandel and Primitivo are names associated with the same grape variety.',items:[{title:'Zinfandel',text:'The name is strongly associated with the United States, especially California.',tone:'sage'},{title:'Primitivo',text:'The name is strongly associated with southern Italy, especially Puglia.',tone:'gold'},{title:'Shared identity',text:'DNA evidence established that the names refer to the same grape variety.',tone:'wine'},{title:'Different wines',text:'Place, farming, ripeness and winemaking can still create different styles.',tone:'ink'}],summary:'Same grape does not mean every bottle tastes the same.',caption:'Label name can provide geographic and stylistic context without guaranteeing style.'}));
components.set('VIS-011', explainer({id:'VIS-011',title:'Variety, clone, scion and rootstock',intro:'These terms describe different levels or parts of a cultivated grapevine.',items:[{title:'Variety',text:'A named grape variety such as Pinot Noir or Chardonnay.',tone:'sage'},{title:'Clone',text:'Selected vine material propagated within a variety for particular traits.',tone:'gold'},{title:'Scion',text:'The fruiting upper part of a grafted vine.',tone:'wine'},{title:'Rootstock',text:'The rooted lower part onto which the scion is grafted.',tone:'ink'}],summary:'A clone belongs within a variety; it is not a separate grape variety.',caption:'A simplified relationship. Not every vine is grafted and selection systems vary.'}));
components.set('VIS-012', explainer({id:'VIS-012',title:'Wine-glass anatomy and practical shapes',intro:'Glass design changes how aroma is gathered and how the wine reaches your mouth.',items:[{title:'Bowl',text:'Holds the wine and provides space above it for aromas.',tone:'sage'},{title:'Rim',text:'The opening affects aroma concentration and the drinking angle.',tone:'gold'},{title:'Stem and base',text:'Provide handling and stability while reducing contact with the bowl.',tone:'wine'},{title:'Practical choice',text:'A clean, clear, tulip-shaped glass works for many wine styles.',tone:'ink'}],summary:'Cleanliness and a useful bowl shape matter more than owning many specialised glasses.',caption:'Shape can influence perception, but it cannot repair a flawed wine.'}));
components.set('VIS-016', explainer({id:'VIS-016',title:'Why Hastings River vineyard sites vary',intro:'A warm, humid regional description still contains meaningful local differences.',items:[{title:'Elevation',text:'Higher and lower sites can experience different temperatures and exposure.',tone:'sage'},{title:'Rainfall and humidity',text:'Water and disease pressure vary with season, location and airflow.',tone:'gold'},{title:'Terrain and soils',text:'Slope, drainage and soil properties influence vine conditions.',tone:'wine'},{title:'Grower response',text:'Variety, canopy, disease management and harvest timing adapt to each site.',tone:'ink'}],summary:'Regional climate sets context; individual sites and seasons shape the detail.',caption:'A site-variation framework, not a precise map or vineyard ranking.'}));
components.set('VIS-026', explainer({id:'VIS-026',title:'How lees stirring works',intro:'Settled yeast material is deliberately moved back through the wine.',items:[{title:'Lees settle',text:'Spent yeast and other fine particles collect after fermentation.',tone:'sage'},{title:'Stir',text:'A tool or other controlled movement resuspends the lees.',tone:'gold'},{title:'Contact',text:'The wine spends renewed contact time with the dispersed lees.',tone:'wine'},{title:'Repeat or stop',text:'Frequency and duration depend on the wine and the intended result.',tone:'ink'}],summary:'Lees stirring is an active choice within lees ageing—not a guarantee of flavour.',caption:'A simplified bâtonnage cycle. Vessel, timing and wine condition matter.'}));
components.set('VIS-027', explainer({id:'VIS-027',title:'Tempranillo vs Sangiovese',intro:'Both are food-friendly red grapes, but their broad structural tendencies differ.',items:[{title:'Tempranillo',text:'Often shows red to dark fruit, moderate acidity and savoury or oak-aged character.',tone:'sage'},{title:'Sangiovese',text:'Often shows red cherry, herbal or savoury notes with lively acidity.',tone:'gold'},{title:'Shared ground',text:'Both can range from youthful and fruity to structured and ageworthy.',tone:'wine'},{title:'Choose by dish',text:'Consider acidity, tannin, body, sauce and cooking method—not grape name alone.',tone:'ink'}],summary:'Tempranillo often leans rounder; Sangiovese often leans brighter—but styles overlap.',caption:'Broad tendencies only. Region, vintage and winemaking can outweigh variety stereotypes.'}));
components.set('VIS-035', explainer({id:'VIS-035',title:'How a solera system moves wine',intro:'Small fractions move through ageing tiers while older wine remains in the system.',items:[{title:'Young wine enters',text:'Newer wine is added to the youngest tier or criadera.',tone:'sage'},{title:'Fractional movement',text:'A portion moves from younger tiers towards older tiers.',tone:'gold'},{title:'Solera tier',text:'The oldest tier supplies a fraction for bottling or further use.',tone:'wine'},{title:'Refresh',text:'Removed volumes are replenished, preserving continuity across withdrawals.',tone:'ink'}],summary:'A solera blends many ages through repeated fractional movement.',caption:'A simplified tiered flow. Real systems differ in scale, timing and number of criaderas.'}));
components.set('VIS-036', explainer({id:'VIS-036',title:'Reverse osmosis in winemaking',intro:'Pressure pushes selected small molecules through a membrane while others remain concentrated.',items:[{title:'Wine enters',text:'Wine is supplied to a pressure-driven membrane system.',tone:'sage'},{title:'Membrane separation',text:'A permeate passes through while a retentate remains on the feed side.',tone:'gold'},{title:'Treat a fraction',text:'A selected stream may undergo a targeted adjustment.',tone:'wine'},{title:'Recombine carefully',text:'Components may be recombined according to the intended technical outcome.',tone:'ink'}],summary:'Reverse osmosis separates components; it is not simple filtration of flavour.',caption:'A simplified pathway. Equipment, targets and legal permissions vary.'}));
components.set('VIS-037', explainer({id:'VIS-037',title:'Why Chilean wine regions vary',intro:'Chile’s long, narrow geography creates multiple interacting climate influences.',items:[{title:'Pacific Ocean',text:'Cool ocean influence can moderate some coastal areas.',tone:'sage'},{title:'Coastal ranges',text:'Terrain affects how marine air and cloud reach inland sites.',tone:'gold'},{title:'Central valleys',text:'Distance from the coast and local heat patterns influence ripening.',tone:'wine'},{title:'Andes',text:'Elevation, cold air and snowmelt water shape many eastern sites.',tone:'ink'}],summary:'Geography influences wine style; it does not determine flavour by itself.',caption:'A west-to-east context diagram, not a legal-boundary map.'}));
components.set('VIS-039', explainer({id:'VIS-039',title:'How naturally frozen grapes become Icewine',intro:'Grapes freeze on the vine and are pressed while still frozen.',items:[{title:'Leave grapes',text:'Healthy ripe grapes remain on the vine into freezing conditions.',tone:'sage'},{title:'Natural freeze',text:'Water inside the berries freezes under qualifying cold weather.',tone:'gold'},{title:'Press frozen',text:'Frozen water stays behind while a small amount of concentrated juice is extracted.',tone:'wine'},{title:'Slow fermentation',text:'The sugar-rich juice ferments with difficulty into an intensely sweet wine.',tone:'ink'}],summary:'Natural freezing concentrates the juice before fermentation.',caption:'A simplified Icewine pathway. Legal definitions and temperature requirements vary by country.'}));
components.set('VIS-041', explainer({id:'VIS-041',title:'England, Great Britain and the United Kingdom',intro:'These geographic names overlap, but they are not interchangeable.',items:[{title:'England',text:'One country on the island of Great Britain.',tone:'sage'},{title:'Great Britain',text:'The island containing England, Scotland and Wales.',tone:'gold'},{title:'United Kingdom',text:'England, Scotland, Wales and Northern Ireland together.',tone:'wine'},{title:'Wine label context',text:'“English wine” refers specifically to England, not automatically the whole UK.',tone:'ink'}],summary:'England is part of Great Britain, which is part of the United Kingdom.',caption:'A political-geography relationship explainer, not a wine appellation map.'}));

function orientationMap({id, title, intro, outline, region, places, hierarchy, summary, source}) {
  const placeHtml = places.map(place => `<g class="wd-map__place"><circle cx="${place.x}" cy="${place.y}" r="5"/><text x="${place.x + 10}" y="${place.y + 5}">${esc(place.label)}</text></g>`).join('');
  const hierarchyHtml = hierarchy.map((item, index) => `<li><span>${index + 1}</span>${esc(item)}</li>`).join('');
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-map" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy map explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-map__layout"><svg class="wd-map__svg" viewBox="0 0 520 360" role="img" aria-labelledby="${id}-svg-title ${id}-svg-desc"><title id="${id}-svg-title">${esc(title)} orientation schematic</title><desc id="${id}-svg-desc">A simplified orientation diagram showing the highlighted wine area and named reference places. It does not show a legal GI boundary.</desc><path class="wd-map__land" d="${outline}"/><path class="wd-map__region" d="${region}"/>${placeHtml}<g class="wd-map__north"><path d="M470 66V26M470 26l-8 14M470 26l8 14"/><text x="464" y="20">N</text></g></svg><div class="wd-map__key"><p>Geographic hierarchy</p><ol>${hierarchyHtml}</ol><p class="wd-map__notice">Orientation schematic—not a legal boundary map.</p></div></div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>Source: Wine Australia Register of Protected GIs and Open Data Hub. ${esc(source)}</figcaption></figure>`;
}

function officialBoundaryMap({id, title, intro, boundary, places, hierarchy, summary, source}) {
  const placeHtml = places.map(place => {
    const labelX = place.labelX ?? place.x + 10;
    const labelY = place.labelY ?? place.y + 5;
    if (place.kind === 'city') return `<g class="wd-map__place wd-map__place--city"><path class="wd-map__leader" d="M${place.x} ${place.y} L${labelX - 6} ${labelY - 5}"/><rect x="${place.x - 5}" y="${place.y - 5}" width="10" height="10" rx="1"/><text x="${labelX}" y="${labelY}">${esc(place.label)}</text></g>`;
    return `<g class="wd-map__place"><circle cx="${place.x}" cy="${place.y}" r="5"/><text x="${labelX}" y="${labelY}">${esc(place.label)}</text></g>`;
  }).join('');
  const hierarchyHtml = hierarchy.map((item, index) => `<li><span>${index + 1}</span>${esc(item)}</li>`).join('');
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-map" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy map explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-map__layout"><svg class="wd-map__svg" viewBox="0 0 520 360" role="img" aria-labelledby="${id}-svg-title ${id}-svg-desc"><title id="${id}-svg-title">${esc(title)}</title><desc id="${id}-svg-desc">The recognisable Tasmania coastline and Wine Australia regional GI geometry, with approximate reference points for commonly used growing-area names.</desc><path class="wd-map__official-boundary" d="${boundary}"/>${placeHtml}<g class="wd-map__north"><path d="M470 66V26M470 26l-8 14M470 26l8 14"/><text x="464" y="20">N</text></g></svg><div class="wd-map__key"><p>Geographic hierarchy</p><ol>${hierarchyHtml}</ol><p class="wd-map__notice">Filled shape: Wine Australia’s spatial translation of the Tasmania GI. Points: approximate orientation only.</p></div></div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>Source: Wine Australia Register of Protected GIs and Open Data Hub. ${esc(source)}</figcaption></figure>`;
}

function projectStatePoint(crop, lon, lat) {
  const [cropX,cropY,cropW,cropH] = crop;
  const viewport = {x:15,y:15,w:490,h:330};
  const scale = Math.min(viewport.w/cropW, viewport.h/cropH);
  const renderedW = cropW*scale, renderedH = cropH*scale;
  const originX = viewport.x+(viewport.w-renderedW)/2, originY = viewport.y+(viewport.h-renderedH)/2;
  const nativeX = 177.91+(lon-129)*(310.49-177.91)/12;
  const nativeY = 180.42+(-lat-26)*(217.79-180.42)/3;
  return [originX+(nativeX-cropX)*scale,originY+(nativeY-cropY)*scale];
}

function officialGeometryOnState(data, crop) {
  const coordinates = data.paths.flatMap(path => [...path.matchAll(/(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)/g)].map(match => [Number(match[1]),Number(match[2])]));
  const xs = coordinates.map(point => point[0]), ys = coordinates.map(point => point[1]);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  const [minLon,minLat,maxLon,maxLat] = data.bbox;
  const projectLocal = (x,y) => {
    const lon = minLon + ((x-minX)/(maxX-minX))*(maxLon-minLon);
    const lat = maxLat - ((y-minY)/(maxY-minY))*(maxLat-minLat);
    return projectStatePoint(crop,lon,lat);
  };
  const paths = data.paths.map(path => path.replace(/(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)/g,(_,x,y) => {
    const projected = projectLocal(Number(x),Number(y));
    return `${projected[0].toFixed(1)} ${projected[1].toFixed(1)}`;
  }));
  return {paths,projectLocal};
}

function officialRegionMap({id, title, intro, hierarchy, summary, source, reference, labels = [], locator}) {
  const data = officialMapData[id];
  if (!data) throw new Error(`Missing official map data: ${id}`);
  if (!locator) throw new Error(`Missing state locator configuration: ${id}`);
  const geometry = officialGeometryOnState(data,locator.crop);
  const places = [...data.markers, ...labels].map(place => {
    if (place.kind === 'label') {
      const point=geometry.projectLocal(place.x,place.y);
      return {...place,x:point[0],y:point[1]};
    }
    const point=geometry.projectLocal(place.x,place.y);
    return {...place,x:point[0],y:point[1],labelX:undefined,labelY:undefined};
  });
  const placeHtml = places.map(place => {
    if (place.kind === 'label') return `<text class="wd-map__zone-label" x="${place.x}" y="${place.y}">${esc(place.label)}</text>`;
    const labelX = place.labelX ?? place.x + 10;
    const labelY = place.labelY ?? place.y + 5;
    if (place.kind === 'city') return `<g class="wd-map__place wd-map__place--city"><rect x="${place.x - 5}" y="${place.y - 5}" width="10" height="10" rx="1"/><text x="${labelX}" y="${labelY}">${esc(place.label)}</text></g>`;
    return `<g class="wd-map__place"><circle cx="${place.x}" cy="${place.y}" r="5"/><text x="${labelX}" y="${labelY}">${esc(place.label)}</text></g>`;
  }).join('');
  const hierarchyHtml = hierarchy.map((item, index) => `<li><span>${index + 1}</span>${esc(item)}</li>`).join('');
  const pathHtml = geometry.paths.map(path => `<path class="wd-map__official-boundary wd-map__official-boundary--context" d="${path}"/>`).join('');
  const referenceHtml = reference ? `<text class="wd-map__reference" x="62" y="59">${esc(reference)}</text>` : '';
  const integratedMap = `<svg class="wd-map__svg" viewBox="0 0 520 360" role="img" aria-labelledby="${id}-svg-title ${id}-svg-desc"><title id="${id}-svg-title">${esc(title)}</title><desc id="${id}-svg-desc">The official wine-region geometry shown in its correct position on a recognisable state map, with city and town references.</desc><image href="${esc(locator.asset)}" x="15" y="15" width="490" height="330"/>${pathHtml}${placeHtml}${referenceHtml}<g class="wd-map__north"><path d="M470 66V26M470 26l-8 14M470 26l8 14"/><text x="464" y="20">N</text></g></svg>`;
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-map" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy map explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-map__layout">${integratedMap}<div class="wd-map__key"><p>Geographic hierarchy</p><ol>${hierarchyHtml}</ol><p class="wd-map__notice">Burgundy area: official Wine Australia spatial translation. Square: city. Circle: local reference.</p></div></div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>State base adapted from “Australian states map” by PoliticsMaps, CC0/public domain. Regional boundary: Wine Australia Register of Protected GIs and Open Data Hub. ${esc(source)}</figcaption></figure>`;
}

function nationalWineMap({id, title, intro, hierarchy, summary}) {
  // Coordinates are georeferenced to the stencil using the 129°E, 138°E and
  // 141°E state borders plus the 26°S and 29°S boundaries—not hand-placed.
  const cities = [{label:'Perth',x:102.8,y:216.1,tx:70,ty:205},{label:'Adelaide',x:306.2,y:246.1,tx:255,ty:263},{label:'Melbourne',x:363.1,y:275.2,tx:326,ty:296},{label:'Sydney',x:419,y:235.4,tx:433,ty:247},{label:'Brisbane',x:435.2,y:170.9,tx:446,ty:162},{label:'Hobart',x:384.2,y:326.3,tx:396,ty:338}];
  const regions = [{label:'Margaret River',x:95.5,y:236.2,tx:45,ty:251},{label:'Barossa Valley',x:309.4,y:242.1,tx:242,ty:226},{label:'Yarra Valley',x:367.5,y:273.5,tx:380,ty:283},{label:'Hunter',x:418,y:224.6,tx:431,ty:219},{label:'Granite Belt',x:424.7,y:182.3,tx:350,ty:180}];
  const marker = (place, klass) => `<g class="${klass}"><path class="wd-map__callout" d="M${place.x} ${place.y} L${place.tx} ${place.ty - 4}"/><circle cx="${place.x}" cy="${place.y}" r="${klass.includes('wine') ? 5 : 4}"/><text x="${place.tx}" y="${place.ty}">${esc(place.label)}</text></g>`;
  const cityHtml = cities.map(place => marker(place,'wd-map__city-marker')).join('');
  const wineHtml = regions.map(place => marker(place,'wd-map__wine-marker')).join('');
  const hierarchyHtml = hierarchy.map((item, index) => `<li><span>${index + 1}</span>${esc(item)}</li>`).join('');
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-map" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy map explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-map__layout"><svg class="wd-map__svg" viewBox="0 0 520 360" role="img" aria-labelledby="${id}-svg-title ${id}-svg-desc"><title id="${id}-svg-title">${esc(title)}</title><desc id="${id}-svg-desc">A clean map of Australia with state boundaries, representative registered wine regions and capital-city references.</desc><image class="wd-map__national-stencil" href="/assets/australian-states-cc0.svg" x="65" y="10" width="395" height="340"/>${wineHtml}${cityHtml}</svg><div class="wd-map__key"><p>Geographic hierarchy</p><ol>${hierarchyHtml}</ol><p class="wd-map__notice">Burgundy dots: representative wine regions. Black dots: capital-city references.</p></div></div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>Base map: “Australian states map” by PoliticsMaps, CC0/public domain. Wine-region locations are orientation references based on Wine Australia’s Register of Protected GIs; textual GI descriptions remain the legal definitions.</figcaption></figure>`;
}

function stateStencilMap({id, asset, crop, title, intro, hierarchy, summary, places}) {
  const [cropX,cropY,cropW,cropH] = crop;
  const viewport = {x:15,y:15,w:490,h:330};
  const scale = Math.min(viewport.w/cropW, viewport.h/cropH);
  const renderedW = cropW*scale, renderedH = cropH*scale;
  const originX = viewport.x+(viewport.w-renderedW)/2, originY = viewport.y+(viewport.h-renderedH)/2;
  const project = (lon,lat) => projectStatePoint(crop,lon,lat);
  const markerHtml = places.map(place => {
    const projected=project(place.lon,place.lat), x=projected[0]+(place.nudgeX??0), y=projected[1]+(place.nudgeY??0), tx=x+(place.dx??9), ty=y+(place.dy??-8);
    const klass=place.kind==='city'?'wd-map__city-marker':'wd-map__wine-marker';
    return `<g class="${klass}"><path class="wd-map__callout" d="M${x.toFixed(1)} ${y.toFixed(1)} L${tx.toFixed(1)} ${(ty-4).toFixed(1)}"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${place.kind==='city'?4:5}"/><text x="${tx.toFixed(1)}" y="${ty.toFixed(1)}">${esc(place.label)}</text></g>`;
  }).join('');
  const hierarchyHtml=hierarchy.map((item,index)=>`<li><span>${index+1}</span>${esc(item)}</li>`).join('');
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-map" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy map explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-map__layout"><svg class="wd-map__svg" viewBox="0 0 520 360" role="img" aria-labelledby="${id}-svg-title ${id}-svg-desc"><title id="${id}-svg-title">${esc(title)}</title><desc id="${id}-svg-desc">State orientation map with verified capital-city and representative wine-region locations.</desc><image href="${asset}" x="15" y="15" width="490" height="330"/>${markerHtml}</svg><div class="wd-map__key"><p>Geographic hierarchy</p><ol>${hierarchyHtml}</ol><p class="wd-map__notice">Highlighted shape: state orientation. Burgundy dots: representative wine regions. Black dot: capital-city reference.</p></div></div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>Base map adapted from “Australian states map” by PoliticsMaps, CC0/public domain. Locations are projected from verified coordinates; detailed GI boundaries appear on regional maps.</figcaption></figure>`;
}

function internationalOrientationMap({id,country,title,intro,hierarchy,summary,places,links=[],notice,caption}) {
  const data=internationalMapData[country];
  if(!data) throw new Error(`Missing international map data: ${country}`);
  const [minLon,minLat,maxLon,maxLat]=data.bbox;
  const mapWidth=440,mapHeight=320,mapPad=12;
  const mapScale=Math.min((mapWidth-mapPad*2)/(maxLon-minLon),(mapHeight-mapPad*2)/(maxLat-minLat));
  const mapOriginX=(mapWidth-(maxLon-minLon)*mapScale)/2,mapOriginY=(mapHeight-(maxLat-minLat)*mapScale)/2;
  const project=(lon,lat)=>[40+mapOriginX+(lon-minLon)*mapScale,20+mapOriginY+(maxLat-lat)*mapScale];
  const countryPaths=data.paths.map(path=>`<path class="wd-map__country-stencil" d="${path}" transform="translate(40 20)"/>`).join('');
  const highlightPaths=(data.highlightPaths||[]).map(path=>`<path class="wd-map__country-highlight" d="${path}" transform="translate(40 20)"/>`).join('');
  const linkHtml=links.map(link=>{
    const points=link.points.map(point=>project(point.lon,point.lat));
    const line=points.map(point=>point.map(value=>value.toFixed(1)).join(',')).join(' ');
    return `<polygon class="wd-map__orientation-link" points="${line}"/>`;
  }).join('');
  const markerHtml=places.map(place=>{
    const [x,y]=project(place.lon,place.lat),tx=x+(place.dx??10),ty=y+(place.dy??-8);
    const klass=place.kind==='city'?'wd-map__city-marker':'wd-map__wine-marker';
    return `<g class="${klass}"><path class="wd-map__callout" d="M${x.toFixed(1)} ${y.toFixed(1)} L${tx.toFixed(1)} ${(ty-4).toFixed(1)}"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${place.kind==='city'?4:5}"/><text x="${tx.toFixed(1)}" y="${ty.toFixed(1)}">${esc(place.label)}</text></g>`;
  }).join('');
  const hierarchyHtml=hierarchy.map((item,index)=>`<li><span>${index+1}</span>${esc(item)}</li>`).join('');
  return `<figure class="learning-visual" id="${id.toLowerCase()}"><div class="wd-explainer wd-map wd-map--international" role="group" aria-labelledby="${id}-title" aria-describedby="${id}-summary"><p class="wd-explainer__eyebrow">WineDaddy map explainer</p><p class="wd-explainer__title" id="${id}-title">${esc(title)}</p><p class="wd-explainer__intro">${esc(intro)}</p><div class="wd-map__layout"><svg class="wd-map__svg" viewBox="0 0 520 360" role="img" aria-labelledby="${id}-svg-title ${id}-svg-desc"><title id="${id}-svg-title">${esc(title)}</title><desc id="${id}-svg-desc">Country orientation map with verified city and wine-region reference locations.</desc>${countryPaths}${highlightPaths}${linkHtml}${markerHtml}</svg><div class="wd-map__key"><p>Geographic hierarchy</p><ol>${hierarchyHtml}</ol><p class="wd-map__notice">${esc(notice||'Burgundy dots: wine-region references. Black dots: city references. Markers show location, not legal boundaries.')}</p></div></div><p class="wd-explainer__summary" id="${id}-summary"><span>Remember</span><strong>${esc(summary)}</strong></p></div><figcaption>Country base: Natural Earth 1:50m Admin 0 Countries, public domain. ${esc(caption)}</figcaption></figure>`;
}

